/**
 * Finzy — Motor de Gráficos Local em Canvas (assets/js/chart.min.js)
 * 
 * Implementação leve e nativa para renderização de gráficos comparativos
 * de colunas em HTML5 Canvas, sem nenhuma dependência de CDN externa.
 */

(function (global) {
    'use strict';

    class FinzyChart {
        constructor(canvasElement, config) {
            if (typeof canvasElement === 'string') {
                this.canvas = document.getElementById(canvasElement);
            } else {
                this.canvas = canvasElement;
            }

            if (!this.canvas || !this.canvas.getContext) {
                console.error('FinzyChart: Elemento canvas inválido.');
                return;
            }

            this.ctx = this.canvas.getContext('2d');
            this.config = config || {};
            this.type = this.config.type || 'bar';
            this.data = this.config.data || { labels: [], datasets: [] };
            this.options = this.config.options || {};

            this.init();
        }

        init() {
            this.resizeCanvas();
            window.addEventListener('resize', () => {
                this.resizeCanvas();
                this.render();
            });
            this.render();
        }

        resizeCanvas() {
            const container = this.canvas.parentElement;
            if (container) {
                const rect = container.getBoundingClientRect();
                this.canvas.width = rect.width || 600;
                this.canvas.height = this.options.height || 300;
            } else {
                this.canvas.width = 600;
                this.canvas.height = 300;
            }
        }

        render() {
            const ctx = this.ctx;
            const width = this.canvas.width;
            const height = this.canvas.height;

            ctx.clearRect(0, 0, width, height);

            const labels = this.data.labels || [];
            const datasets = this.data.datasets || [];

            if (labels.length === 0 || datasets.length === 0) {
                this.renderEmptyState('Sem dados para exibição no gráfico');
                return;
            }

            const padding = { top: 30, right: 30, bottom: 50, left: 60 };
            const chartWidth = width - padding.left - padding.right;
            const chartHeight = height - padding.top - padding.bottom;

            // Encontra o valor máximo dos dados
            let maxVal = 0;
            datasets.forEach(ds => {
                (ds.data || []).forEach(v => {
                    if (v > maxVal) maxVal = v;
                });
            });

            if (maxVal === 0) maxVal = 100;
            maxVal = Math.ceil(maxVal * 1.15); // Margem de topo

            // Desenha linhas de grade horizontais e rótulos do eixo Y
            const gridSteps = 4;
            ctx.lineWidth = 1;
            ctx.strokeStyle = '#E3E2E6';
            ctx.fillStyle = '#74777F';
            ctx.font = '11px Inter, sans-serif';
            ctx.textAlign = 'right';
            ctx.textBaseline = 'middle';

            for (let i = 0; i <= gridSteps; i++) {
                const yVal = (maxVal / gridSteps) * i;
                const yPos = padding.top + chartHeight - (chartHeight * (i / gridSteps));

                ctx.beginPath();
                ctx.moveTo(padding.left, yPos);
                ctx.lineTo(width - padding.right, yPos);
                ctx.stroke();

                // Formatação simples do valor Y
                const labelStr = yVal >= 1000 ? (yVal / 1000).toFixed(1) + 'k' : Math.round(yVal).toString();
                ctx.fillText('R$ ' + labelStr, padding.left - 8, yPos);
            }

            // Desenha barras e rótulos do eixo X
            const groupCount = labels.length;
            const groupWidth = chartWidth / groupCount;
            const datasetCount = datasets.length;
            const barMargin = 4;
            const totalBarSpace = groupWidth - 16;
            const barWidth = Math.max(4, Math.min(28, (totalBarSpace / datasetCount) - barMargin));

            ctx.textAlign = 'center';
            ctx.textBaseline = 'top';

            labels.forEach((label, groupIdx) => {
                const groupStartX = padding.left + (groupIdx * groupWidth);
                const groupCenterX = groupStartX + (groupWidth / 2);

                // Rótulo do eixo X
                ctx.fillStyle = '#43474E';
                ctx.font = '11px Inter, sans-serif';
                ctx.fillText(label, groupCenterX, height - padding.bottom + 12);

                // Desenha cada barra do conjunto
                datasets.forEach((ds, dsIdx) => {
                    const val = ds.data[groupIdx] || 0;
                    const barH = (val / maxVal) * chartHeight;
                    const totalGroupBarsW = (datasetCount * barWidth) + ((datasetCount - 1) * barMargin);
                    const barX = groupCenterX - (totalGroupBarsW / 2) + (dsIdx * (barWidth + barMargin));
                    const barY = padding.top + chartHeight - barH;

                    // Cor da barra
                    ctx.fillStyle = ds.backgroundColor || '#022448';
                    
                    // Desenha barra com cantos arredondados no topo
                    const radius = Math.min(4, barWidth / 2);
                    ctx.beginPath();
                    ctx.moveTo(barX, padding.top + chartHeight);
                    ctx.lineTo(barX, barY + radius);
                    ctx.quadraticCurveTo(barX, barY, barX + radius, barY);
                    ctx.lineTo(barX + barWidth - radius, barY);
                    ctx.quadraticCurveTo(barX + barWidth, barY, barX + barWidth, barY + radius);
                    ctx.lineTo(barX + barWidth, padding.top + chartHeight);
                    ctx.closePath();
                    ctx.fill();
                });
            });
        }

        renderEmptyState(message) {
            const ctx = this.ctx;
            const width = this.canvas.width;
            const height = this.canvas.height;

            ctx.fillStyle = '#74777F';
            ctx.font = '14px Inter, sans-serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(message, width / 2, height / 2);
        }
    }

    // Suporte para instanciação via global "Chart" ou "FinzyChart"
    global.FinzyChart = FinzyChart;
    global.Chart = FinzyChart;

})(typeof window !== 'undefined' ? window : this);
